    margin: 0;
}

body {
       height: 100px;
    background-image: url(https://momc-erp.sy/assets/moi_style/icons/pattern.svg);
    background-size: 400px;

    background-color: #054239;
}

/* === CENTERING WRAPPER === */
.print-format-container {
    display: table;
    width: 100%;
    height: 100%;
}

.print-format {
    display: table-cell;
    vertical-align: middle;
    text-align: center; /* centers inline-block child */
    padding: 0;
    background-color: transparent;
}

.print-format > .content-wrapper {
    display: inline-block;
    text-align: right; /* restore RTL alignment inside */
    direction: rtl;
    width: 90%;
    max-width: 160mm;
    padding: 10px;
    background-color: rgba(255, 255, 255, 0.85); /* optional: improve readability */
    border-radius: 8px;
}

/* --- Header --- */
.header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 20px;
    padding: 10px 0;
    border-bottom: 2px solid #4472c4;
}

.header .paragraph {
    font-size: 18px;
    margin: 3px 0;
    font-weight: bold;
}

.header .header-left .paragraph,
.header .left .paragraph {
    text-align: left;
    direction: ltr;
}

.header img {
    margin: 0 auto;
}

/* --- Title --- */
.main-heading .title {
    text-align: center;
    color: #4472c4;
    font-size: 24px;
    font-weight: bold;
    margin: 25px 0 15px;
    text-decoration: underline;
}

/* --- Personal Photo --- */
.personal-image {
    text-align: center;
    margin: 15px 0;
}

.personal-image img {
    width: 100px;
    height: auto;
    border: 2px solid #ddd;
    border-radius: 8px;
    box-shadow: 0 2px 5px rgba(0,0,0,0.1);
}

/* --- Section Styling --- */
.sub-heading {
    background-color: #f0f8ff;
    border: 1px solid #4472c4;
    padding: 10px 15px;
    margin: 25px 0 15px;
    font-size: 18px;
    font-weight: bold;
    color: #2a5298;
    border-radius: 4px;
    text-align: right;
}

/* --- Paragraphs & Fields --- */
.par {
    font-size: 15px;
    margin: 8px 0;
    padding: 0 10px;
    text-align: right;
}

.par b {
    color: #2a5298;
    min-width: 280px;
    display: inline-block;
}

/* Checkbox styling */
.par span.checkmark {
    margin-left: 5px;
    font-size: 18px;
}

/* --- Child Table Entries --- */
.article-entry {
    margin: 15px 0;
    padding: 10px;
    background-color: #fafafa;
    border-right: 3px solid #4472c4;
    border-radius: 4px;
}

.article-entry .par {
    margin: 4px 0;
}

.article-entry hr {
    margin: 15px 0;
    border-color: #ddd;
}

/* --- Horizontal Rule --- */
hr {
    width: 95%;
    margin: 20px auto;
    border: 0;
    border-top: 1px dashed #ccc;
}

/* --- Notes & Violations --- */
.fifth-section .par {
    background-color: #fff9f9;
    padding: 12px;
    border-right: 3px solid #ff6b6b;
    border-radius: 4px;
    margin: 10px 0;
}

/* --- Signature Area --- */
.signature .paragraph {
    padding: 5px 10px;
    margin-left: 10px;
    font-style: italic;
}

/* --- Print Safety --- */
@media print {
    body {
        -webkit-print-color-adjust: exact;
        print-color-adjust: exact;
    }
}

