.top-table, .main-table, .sign-table {
  width: 100%;
  border-collapse: collapse;
  margin-bottom: 10px;
}
.top-table th, .top-table td,
.main-table th, .main-table td,
.sign-table th, .sign-table td {
  border: 1px solid #bfbfbf;
  padding: 8px 10px;
  vertical-align: top;
  font-size: 12px;
