.wide { width: 40%; }
.details { min-height: 60px; white-space: pre-wrap; background: #fff; padding: 6px; }
.cb { display: inline-block; margin: 0 8px; font-size: 14px; color: #333; }
.other { display: inline-block; margin-left: 8px; font-style: italic; color: #333; }

/* Barcode placeholder */
.barcode img { max-height: 40px; display:block; margin-top:6px; }

/* Signatures */
.sign-table th { background: #f5fbfb; color: #004d4d; text-align: center; font-weight: 700; }
.sign-box { height: 70px; border-bottom: 1px solid #000; }

/* Footer */
.footer-section {
  margin-top: 12px;
  padding-top: 8px;
  border-top: 1px solid #ddd;
  display: flex;
  justify-content: center;
  gap: 18px;
  font-size: 11px;
  color: #333;
}

