@media print {
  @page { size: A4 portrait; margin: 10mm; }
  body { -webkit-print-color-adjust: exact; print-color-adjust: exact; }
  .print-container { max-width: none; margin: 0; padding: 0; }
  .logo-img { width: 90px; }
  .main-title { font-size: 18px; }
}

