html:
{%- set row_id = frappe.form_dict.row_id or frappe.form_dict._row_id -%}
{%- set target = namespace(employee=None) -%}

{# البحث في الجدول الفرعي عن الموظف المستهدف #}
{%- for row in doc.approved_participants -%}
    {%- if row.name == row_id -%}
        {%- set target.employee = row -%}
    {%- endif -%}
{%- endfor -%}

{%- if target.employee -%}
    {# جلب مستند الموظف الأصلي للحصول على حقل leave_approver #}
    {%- set emp_doc = frappe.get_doc("Employee", target.employee.employee) -%}
    
    {# جلب بيانات المدير المعتمد #}
    {%- set manager_name = "" -%}
    {%- set manager_signature = "" -%}
    {%- set manager_stamp = "" -%}
    
    {%- if emp_doc.leave_approver -%}
        {%- set manager_user = frappe.get_doc("User", emp_doc.leave_approver) -%}
        {%- set manager_name = manager_user.full_name -%}
        {# جلب التوقيع والختم من دوكتايب User الخاص بالمدير #}
        {%- set manager_signature = manager_user.signature -%}
        {%- set manager_stamp = manager_user.stamp -%}
    {%- endif -%}

