}

.print-container {
    width: 100%;
    max-width: 100%;
    margin: 0 auto;
    padding: 2px;
    box-sizing: border-box;
}

/* 1. الترويسة العلويّة - متوسطة وموازية للصورة */
.header-table {
    width: 100%;
    border-collapse: collapse;
    margin-bottom: 5px;
    border: none !important;
}

.header-table td {
    border: none !important;
    padding: 0;
    vertical-align: middle !important; /* محاذاة شاقولية في المنتصف */
}

.header-right {
    text-align: right;
    width: 32%;
    font-size: 15px;
    font-weight: bold;
    line-height: 1.3;
}

.header-center {
    text-align: center;
    width: 36%;
    font-size: 22px;
    font-weight: bold;
}

.header-left {
    text-align: left;
    width: 32%;
}

.header-logo {
    max-height: 75px;
    width: auto;
    display: inline-block;
    vertical-align: middle;
}

.header-divider {
    border-bottom: 1.5px solid #000;
    margin-bottom: 8px;
}

/* 2. جدول البيانات العلوي */
.info-table {
    width: 100%;
    border-collapse: collapse;
    margin-bottom: 8px;
    border: 1.5px solid #000;
}

.info-table td {
    border: 1px solid #000;
    padding: 4px 3px;
    text-align: center;
    font-size: 12px;
}

.info-table .bg-blue {
    background-color: #d9e5f0;
    font-weight: bold;
}

/* 3. جدول المواد الرئيسي */
.items-table {
    width: 100%;
    border-collapse: collapse;
    margin-bottom: 0;
    border: 1.5px solid #000;
}

.items-table th, 
.items-table td {
    border: 1px solid #000;
    padding: 4px 5px;
    text-align: center;
    font-size: 12px;
}

.items-table th {
    background-color: #cddde9;
    font-weight: bold;
}

.closing-row {
    font-weight: bold;
    text-align: center !important;
    font-size: 12px;
    padding: 4px !important;
    border-top: 1.5px solid #000;
}

/* 4. قسم التواقيع والأختام المتداخلة */
.signatures-container {
    width: 100%;
    border: 1.5px solid #000;
    border-top: none;
    padding: 10px 5px 5px 5px;
    box-sizing: border-box;
}

.signatures-table {
    width: 100%;
    border-collapse: collapse;
    border: none !important;
}

.signatures-table td {
    border: none !important;
    width: 33.33%;
    text-align: center;
    vertical-align: top;
    font-size: 13px;
    padding: 0 2px;
}

.signatures-table .title {
    font-weight: bold;
    font-size: 14px;
    margin-bottom: 2px;
}

.signatures-table .name {
    font-weight: bold;
    font-size: 13px;
    margin-top: 1px;
}

.signatures-table .signed-tag {
    font-size: 11px;
    color: #555;
    margin-top: 1px;
}

/* حاوية تركيب التوقيع فوق الختم */
.img-wrapper {
    position: relative;
    width: 100%;
    height: 90px; /* ارتفاع ثابت يتسع للختم والتوقيع معاً */
    margin-top: 5px;
    display: flex;
    justify-content: center;
    align-items: center;
}

/* الختم في الخلفية */
.stamp-img {
    position: absolute;
    max-height: 80px;
    max-width: 80%;
    object-fit: contain;
    z-index: 1;
    opacity: 0.9;
}

/* التوقيع فوق الختم بشفافية */
.sig-img {
    position: absolute;
    max-height: 65px;
    max-width: 85%;
    object-fit: contain;
    z-index: 2;
    mix-blend-mode: multiply; /* لجعل الخلفية البيضاء للتوقيع شفافة تماماً فوق الختم */
}

/* أصغر هوامش طباعة ممكّنة */
@page {
    size: A4 portrait;
    margin: 3mm;
}

body {
