    margin-top:15px;
    margin-bottom:25px;
    font-size:17px;
}

table th{
    background:#f2f2f2;
    border:1px solid #555;
    padding:10px;
    font-size:18px;
    font-weight:bold;
}

table td{
    border:1px solid #555;
    padding:10px;
    text-align:center;
