}

.stamp{
    width:120px;
    height:120px;
    object-fit:contain;
    background:transparent !important;
    border:none !important;
    transform:rotate(-18deg);
}

/* ================= Footer ================= */

.footer{
    margin-top:50px;
}

.footer-contact{
    display:flex;
    justify-content:center;
    align-items:center;
    gap:25px;
