  font-weight: 700;
}

@page {
  size: 85mm 55mm;
  margin: 0;
}

/*
 * Frappe v15 reads these exact top-level declarations when it builds the
 * wkhtmltopdf command. Keep this selector outside @media: @page alone is not
 * used by Frappe's PDF option parser.
 */
.print-format {
  page-size: Custom;
  page-width: 85mm;
  page-height: 55mm;
  margin-top: 0mm;
  margin-right: 0mm;
  margin-bottom: 0mm;
  margin-left: 0mm;
}

.journalist-card-format,
.journalist-card-format * {
  box-sizing: border-box;
}

.journalist-card-format {
  width: 85mm;
  margin: 0 auto;
  padding: 0;
  direction: ltr;
  color: #000;
  font-size: 0;
  line-height: 0;
}

.journalist-card-format .press-card {
  position: relative;
  width: 85mm;
  height: 55mm;
  margin: 0;
  padding: 0;
  overflow: hidden;
  direction: ltr;
  background-color: #fff;
  background-image: none;
  color: #000;
  font-family: "Qomra Card", Arial, sans-serif;
  font-size: 7pt;
  font-weight: 400;
  line-height: normal;
  page-break-inside: avoid;
  break-inside: avoid;
  -webkit-print-color-adjust: exact;
  print-color-adjust: exact;
}

.journalist-card-format .press-card-front {
  page-break-after: always;
  break-after: page;
  background-image: url("/files/pattern 2.svg"), url("/files/pattern 1.svg");
  background-repeat: no-repeat, no-repeat;
  background-position: 7mm 11mm, 7mm 15mm;
  background-size: 43mm 43mm, 68mm 40mm;
}

.journalist-card-format .press-card-back {
  background-image: url("/files/pattern 1.svg");
  background-repeat: no-repeat;
  background-position: center 14mm;
  background-size: 85mm 45.9mm;
}

/*
 * Background decoration: the guilloche wave field, the geometric star band
 * across the top and (front only) the rosette. It is drawn inline rather than
 * loaded from /files so the card carries its own artwork, and every colour
 * lives on the SVG itself as a presentation attribute, which is the shape
 * QtWebKit handles most reliably while printing.
 */
.journalist-card-format .card-deco {
  display: none;
}

/*
 * Print-safe six-millimetre band. The former external SVG contains live,
 * non-embedded text that QtWebKit can resize and clip while printing.
 * A solid band plus controlled words stays identical in preview and PDF.
 */
.journalist-card-format .press-band {
  position: absolute;
  top: -0.2mm;
  width: 6.2mm;
  height: 55.4mm;
  overflow: hidden;
  z-index: 6;
  background-color: #052522;
  background-image: none !important;
  -webkit-print-color-adjust: exact;
  print-color-adjust: exact;
}

.journalist-card-format .press-band-left {
  left: -0.2mm;
}

.journalist-card-format .press-band-right {
  right: -0.2mm;
}

/*
 * Guilloche-style PRESS texture. The whole texture box is rotated once so the
 * three tracks can be laid out along the band as ordinary horizontal lines,
 * and every word is placed absolutely so the 11mm repeat cannot drift with the
 * font that QtWebKit ends up resolving.
 */
.journalist-card-format .band-texture {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 55.4mm;
  height: 6.2mm;
  margin-left: -27.7mm;
  margin-top: -3.1mm;
  z-index: 1;
  -webkit-transform-origin: center center;
  transform-origin: center center;
}

.journalist-card-format .press-band-left .band-texture {
  -webkit-transform: rotate(-90deg);
  transform: rotate(-90deg);
}

.journalist-card-format .press-band-right .band-texture {
  -webkit-transform: rotate(90deg);
  transform: rotate(90deg);
}

.journalist-card-format .band-track {
  position: absolute;
  width: 0;
  height: 0;
}

.journalist-card-format .band-track span {
  position: absolute;
  top: 0;
  color: #14312c;
  font-family: "Boutros Press", "Qomra Card", Arial, sans-serif;
  font-weight: 700;
  white-space: nowrap;
}

.journalist-card-format .band-word-1 {
  left: 0;
}

.journalist-card-format .band-word-2 {
  left: 11mm;
}

.journalist-card-format .band-word-3 {
  left: 22mm;
}

.journalist-card-format .band-word-4 {
  left: 33mm;
}

.journalist-card-format .band-word-5 {
  left: 44mm;
}

.journalist-card-format .press-card-front .band-track-a {
  left: 6.83mm;
  top: 0.21mm;
}

.journalist-card-format .press-card-front .band-track-b {
  left: 2.46mm;
  top: 2.12mm;
}

.journalist-card-format .press-card-front .band-track-c {
  left: -0.52mm;
  top: 4.55mm;
}

.journalist-card-format .press-card-back .band-track-a {
  left: 1.72mm;
  top: 0.09mm;
}

.journalist-card-format .press-card-back .band-track-b {
  left: 0.54mm;
  top: 2.58mm;
}

.journalist-card-format .press-card-back .band-track-c {
  left: 6.29mm;
  top: 4.55mm;
}

