/*
 * scaleX runs before the rotation, so it narrows the letters, not their height.
 * translateY nudges the word off the line-box centre and onto the optical
 * centre of the band, since PRESS leaves the descender space unused.
 */
.journalist-card-format .press-word-up {
  -webkit-transform: translate(-50%, -50%) rotate(-90deg) translateY(0.22mm) scaleX(0.96);
  transform: translate(-50%, -50%) rotate(-90deg) translateY(0.22mm) scaleX(0.96);
}

.journalist-card-format .press-word-down {
  -webkit-transform: translate(-50%, -50%) rotate(90deg) translateY(0.22mm) scaleX(0.96);
